PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord ?variantWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma lila:hasPOS lila:verb ;
        ontolex:writtenRep ?italianWord ;
        lila:lemmaVariant ?variantLemma .
    ?variantLemma ontolex:writtenRep ?variantWord .
  }
  FILTER(STR(?italianWord) = "distribuire")
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?hypolemmaWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
        ontolex:writtenRep ?italianWord .
    FILTER(STR(?italianWord) = "manifestare")

    ?hypolemma lila:isHypolemma ?italianLemma ;
        ontolex:writtenRep ?hypolemmaWord .
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianLemma ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    ?italianLemma lila:hasPOS lila:noun .
    ?italianLemma ontolex:writtenRep ?italianWord .
    FILTER(REGEX(STR(?italianWord), "oria$"))
  }
}
ORDER BY ?italianWord

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(*) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:noun ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(REGEX(STR(?italianWord), "^antr", "i"))
  }
}

# This query counts Italian verbs in LiITA that are classified as irregular third-conjugation verbs (inflection type c3i).
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:verb ;
                  lila:hasInflectionType ?inflectionType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(CONTAINS(STR(?inflectionType), "c3i"))
  }
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?kindWr ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?fiumeWord ontolex:canonicalForm [ ontolex:writtenRep ?fiumeWr ] ;
               ontolex:sense ?fiumeSense .
    FILTER(STR(?fiumeWr) = "fiume")

    # ?fiumeSense is a hypernym of (more general than) ?kindSense
    ?fiumeSense lexinfo:hypernym ?kindSense .

    ?kindWord ontolex:sense ?kindSense ;
              ontolex:canonicalForm [ ontolex:writtenRep ?kindWr ] .
    OPTIONAL { ?kindSense skos:definition ?definition }
  }
}
ORDER BY ?kindWr

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?partWr ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?wholeWord ontolex:canonicalForm [ ontolex:writtenRep ?wholeWr ] ;
               ontolex:sense ?wholeSense .
    FILTER(STR(?wholeWr) = "paglia")

    ?partSense lexinfo:partMeronym ?wholeSense .

    ?partWord ontolex:sense ?partSense ;
              ontolex:canonicalForm [ ontolex:writtenRep ?partWr ] .

    OPTIONAL { ?partSense skos:definition ?definition }
  }
}
ORDER BY ?partWr

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?antonymWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] .
    FILTER(STR(?wr) = "popolato")
    ?word ontolex:sense ?sense .
    { ?sense lexinfo:antonym ?antonymSense . }
    UNION
    { ?antonymSense lexinfo:antonym ?sense . }
    ?antonymWord ontolex:sense ?antonymSense ;
                 ontolex:canonicalForm [ ontolex:writtenRep ?antonymWord ] .
  }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?writtenRep ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
          ontolex:sense [ skos:definition ?definition ] .
    FILTER(STRSTARTS(STR(?definition), "trattare"))
  }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(DISTINCT ?sense) AS ?count)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?lexicalEntry ontolex:canonicalForm [ ontolex:writtenRep ?lemma ] ;
                  ontolex:sense ?sense .
    FILTER(STR(?lemma) = "penetrare")
  }
}

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:sense ?sense .
    ?sense complit:hasSemanticType <http://simpleOntology#Opening> .
  }
  ?word ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?italianWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:sense ?sense ;
          ontolex:canonicalForm [ ontolex:writtenRep ?italianWord ] .
    ?sense complit:hasTrait ?trait .
    FILTER(REGEX(STR(?trait), "LIVESTOCK_FARMING", "i"))
  }
}

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?purposeWord ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] ;
          ontolex:sense ?sense .
    FILTER(STR(?wr) = "falò")
    ?sense complit:usedFor ?purposeSense .
    OPTIONAL {
      ?purposeEntry ontolex:sense ?purposeSense ;
                    ontolex:canonicalForm [ ontolex:writtenRep ?purposeWord ] .
    }
    OPTIONAL {
      ?purposeSense skos:definition ?definition .
    }
  }
}

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?adjectiveWr
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] ;
          ontolex:sense ?nounSense .
    FILTER(STR(?wr) = "dinamismo")
    ?nounSense complit:deadjectivalNoun ?adjectiveSense .
    ?adjectiveWord ontolex:sense ?adjectiveSense ;
                   ontolex:canonicalForm [ ontolex:writtenRep ?adjectiveWr ] .
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?sicilianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  FILTER(STR(?italianWord) = "trovarsi")

  ?translationEntry ontolex:canonicalForm ?italianLemma ;
                    vartrans:translatableAs ?sicilianLexEntry .

  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord
WHERE {
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .
  FILTER(STR(?sicilianWord) = "nsiccumari")
  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?italianLexEntry vartrans:translatableAs ?sicilianLexEntry ;
                   ontolex:canonicalForm ?italianLemma .
  ?italianLemma ontolex:writtenRep ?italianWord .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?sicilianWord
WHERE {
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .
  FILTER(REGEX(STR(?sicilianWord), "nza$", "i"))
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(DISTINCT ?parmigianoLemma) AS ?count)
WHERE {
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?parmigianoWord .
  FILTER(REGEX(STR(?parmigianoWord), "ros$", "i"))
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?italianWord ?emotionLabel
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(STR(?italianWord) = "scrittura")
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (MAX(?polarityValue) AS ?maxPolarityValue) (MIN(?polarityValue) AS ?minPolarityValue)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(STR(?italianWord) = "coltura")
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity ;
                 marl:hasPolarityValue ?polarityValue .
}

# Hyponyms of "formaggio" (CompL-it) with their Sicilian translations.
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?sicilianWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?seed ontolex:canonicalForm [ ontolex:writtenRep ?seedWr ] ;
          ontolex:sense ?seedSense .
    FILTER(STR(?seedWr) = "formaggio")
    ?hyponymSense lexinfo:hyponym ?seedSense .
    ?hyponymWord ontolex:sense ?hyponymSense .
  }
  ?hyponymWord ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?sicilianLexEntry .
  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .
}

# Italian words whose CompL-it definition starts with "usare", with their Parmigiano translations.
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?definition ?parmigianoWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:sense ?sense .
    ?sense skos:definition ?definition .
    FILTER(STRSTARTS(STR(?definition), "usare"))
  }
  ?word ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
        ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?italianEntry ontolex:canonicalForm ?italianLemma ;
      vartrans:translatableAs ?parmigianoEntry .
  ?parmigianoEntry ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
      ontolex:writtenRep ?parmigianoWord .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?parmigianoWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:noun .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion elita:Fiducia .
  }

  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?parmigianoLexEntry .
  ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?parmigianoWord .
}
ORDER BY ?italianWord

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?italianWord ?polarityValue ?sicilianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
        ontolex:writtenRep ?italianWord ;
        lila:hasPOS lila:adjective .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
      marl:hasPolarity ?polarity ;
      marl:hasPolarityValue ?polarityValue .
  FILTER(xsd:float(?polarityValue) > 0.5)
  ?italianSicilianLexEntry ontolex:canonicalForm ?italianLemma ;
      vartrans:translatableAs ?sicilianLexEntry .
  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
      ontolex:writtenRep ?sicilianWord .
}
ORDER BY DESC(?polarityValue)

# Nouns associated with the emotion Anticipation (Aspettativa) in ELIta that have a positive Sentix polarity.
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord ?polarityValue
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:noun ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion elita:Aspettativa .
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity marl:Positive ;
                 marl:hasPolarityValue ?polarityValue .
}
ORDER BY DESC(?polarityValue)

PREFIX elita: <http://w3id.org/elita/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX semiotics: <http://www.ontologydesignpatterns.org/cp/owl/semiotics.owl#>

SELECT DISTINCT ?italianWord ?emotionLabel
WHERE {
    # Get words with SIMPLE semantic type RelationalProperty from CompL-it
    SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?word ontolex:sense ?sense .
        ?sense semiotics:hasSemanticType ?semType .
        FILTER(REGEX(STR(?semType), "RelationalProperty", "i"))
    }

    # Link CompL-it word to LiIta lemma via shared URI
    ?word ontolex:canonicalForm ?italianLemma .
    GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType ;
                      ontolex:writtenRep ?italianWord .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    }

    # Emotion association in ELIta (different entry from lemma)
    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
        ?emotion rdfs:label ?emotionLabel .
    }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?italianWord ?emotionLabel
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?whole ontolex:canonicalForm [ ontolex:writtenRep ?wholeWr ] ;
           ontolex:sense ?wholeSense .
    FILTER(STR(?wholeWr) = "zodiaco")
    ?partSense lexinfo:partMeronym ?wholeSense .
    ?partWord ontolex:sense ?partSense .
  }

  ?partWord ontolex:canonicalForm ?italianLemma .

  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?italianWord ?parmigianoWord (MAX(?polarityValue) AS ?maxPolarityValue)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:adjective ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(REGEX(STR(?italianWord), "noso$", "i"))
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity ;
                 marl:hasPolarityValue ?polarityValue .

  ?italianParmigianoLexEntry ontolex:canonicalForm ?italianLemma ;
                              vartrans:translatableAs ?parmigianoLexEntry .

  ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?parmigianoWord .
}
GROUP BY ?italianWord ?parmigianoWord
ORDER BY DESC(?maxPolarityValue)

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?italianWord ?emotionLabel
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:adjective ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }

  FILTER(?emotion IN (elita:Amore, elita:Disgusto))
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS ?pos ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(?pos IN (lila:noun, lila:adjective))
    FILTER(REGEX(STR(?italianWord), "iuto$", "i"))
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity marl:Negative .
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?writtenRep ?relationType
WHERE {
  {
    SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
      ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] ;
            ontolex:sense ?sense .
      FILTER(STR(?wr) = "capinera")
      ?sense lexinfo:hypernym ?resultSense .
      ?resultWord ontolex:sense ?resultSense ;
                  ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
    }
    BIND("hyponym" AS ?relationType)
  }
  UNION
  {
    SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
      ?word2 ontolex:canonicalForm [ ontolex:writtenRep ?wr2 ] ;
             ontolex:sense ?sense2 .
      FILTER(STR(?wr2) = "capinera")
      ?resultSense2 lexinfo:partMeronym ?sense2 .
      ?resultWord2 ontolex:sense ?resultSense2 ;
                   ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
    }
    BIND("meronym" AS ?relationType)
  }
}
ORDER BY ?relationType ?writtenRep

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?italianWord ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    # Find "cibo" and its sense
    ?cibo ontolex:canonicalForm [ ontolex:writtenRep ?ciboWr ] ;
          ontolex:sense ?ciboSense .
    FILTER(STR(?ciboWr) = "cibo")

    # Level 1: direct hyponyms of "cibo"
    # lexinfo:hypernym points FROM general TO specific
    ?ciboSense lexinfo:hypernym ?level1Sense .

    # Level 2: hyponyms of the level-1 hyponyms
    ?level1Sense lexinfo:hypernym ?level2Sense .

    # Get the words at level 2
    ?level2Word ontolex:sense ?level2Sense ;
                ontolex:canonicalForm [ ontolex:writtenRep ?italianWord ] .

    OPTIONAL { ?level2Sense skos:definition ?definition }
  }
}
ORDER BY ?italianWord

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?level2Wr
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] ;
          ontolex:sense ?menuSense .
    FILTER(STR(?wr) = "menu")

    # Level 1: direct hypernyms of "menu"
    ?menuSense lexinfo:hyponym ?level1Sense .

    # Level 2: hypernyms of the hypernyms
    ?level1Sense lexinfo:hyponym ?level2Sense .

    ?level2Word ontolex:sense ?level2Sense ;
                ontolex:canonicalForm [ ontolex:writtenRep ?level2Wr ] .
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?hypernymWr
WHERE {
  # Step 1: Find Sicilian lemma 'abbattimentu'
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .
  FILTER(STR(?sicilianWord) = "abbattimentu")

  # Step 2: Find Sicilian lexical entry with this lemma
  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .

  # Step 3: Find Italian lexical entry that translates TO this Sicilian entry (Italian → Sicilian)
  ?italianLexEntry vartrans:translatableAs ?sicilianLexEntry ;
                   ontolex:canonicalForm ?italianLemma .

  # Step 4: Get Italian lemma info from main data graph
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  # Step 5: Find hypernyms in CompL-it using shared lexical entry URI as natural join variable
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?italianLexEntry ontolex:sense ?sense .
    ?sense lexinfo:hyponym ?hypernymSense .
    ?hypernymWord ontolex:sense ?hypernymSense ;
                  ontolex:canonicalForm [ ontolex:writtenRep ?hypernymWr ] .
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?parmigianoWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] .
    FILTER(STR(?wr) = "conclusivo")

    ?word ontolex:sense ?sense .

    { ?sense lexinfo:approximateSynonym ?synonymSense . }
    UNION
    { ?synonymSense lexinfo:approximateSynonym ?sense . }

    ?synonymWord ontolex:sense ?synonymSense .
  }

  # Link synonym word (shared URI) to LiITA
  ?synonymWord ontolex:canonicalForm ?italianLemma .

  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  # Parmigiano translation
  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?parmigianoLexEntry .
  ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?parmigianoWord .
}

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?nounWr ?hypernymWr
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    # Step 1: Find the adjective 'pervicace'
    ?adjWord ontolex:canonicalForm [ ontolex:writtenRep ?adjWr ] ;
             ontolex:sense ?adjectiveSense .
    FILTER(STR(?adjWr) = "pervicace")

    # Step 2: Find the deadjectival noun derived from the adjective
    ?nounSense complit:deadjectivalNoun ?adjectiveSense .
    ?nounWord ontolex:sense ?nounSense ;
              ontolex:canonicalForm [ ontolex:writtenRep ?nounWr ] .

    # Step 3: Find hypernyms of the deadjectival noun
    # lexinfo:hyponym points FROM specific TO general (counterintuitive!)
    ?nounSense lexinfo:hyponym ?hypernymSense .
    ?hypernymWord ontolex:sense ?hypernymSense ;
                  ontolex:canonicalForm [ ontolex:writtenRep ?hypernymWr ] .
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
