    ?tumuloWord ontolex:canonicalForm [ ontolex:writtenRep ?tumuloWr ] ;
                ontolex:sense ?tumuloSense .
    FILTER(STR(?tumuloWr) = "tumulo")

    # Find common hypernyms: lexinfo:hyponym points FROM specific TO general
    ?dossoSense lexinfo:hyponym ?commonHypernymSense .
