PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?parmigianoWord
WHERE {
  # Step 1: Find the Parmigiano translation(s) of 'crapulone'
  GRAPH <http://liita.it/data> {
    ?crapuloneLemma a ?crapuloneLemmaType ;
                    ontolex:writtenRep ?crapuloneWord .
    FILTER(?crapuloneLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(STR(?crapuloneWord) = "crapulone")
  }

  ?crapuloneEntry ontolex:canonicalForm ?crapuloneLemma ;
                  vartrans:translatableAs ?crapuloneParmigianoEntry .

  ?crapuloneParmigianoEntry ontolex:canonicalForm ?crapuloneParmigianoLemma .
  ?crapuloneParmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                             ontolex:writtenRep ?parmigianoWord .

  # Step 2: Find OTHER Parmigiano lemmas with the same written form
  ?otherParmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                         ontolex:writtenRep ?parmigianoWord .

  ?otherParmigianoEntry ontolex:canonicalForm ?otherParmigianoLemma .

  # Step 3: Find the Italian word(s) that translate to those Parmigiano entries
  ?otherItalianEntry vartrans:translatableAs ?otherParmigianoEntry ;
                     ontolex:canonicalForm ?italianLemma .

  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  # Exclude 'crapulone' itself
  FILTER(STR(?italianWord) != "crapulone")
}
ORDER BY ?parmigianoWord ?italianWord

PREFIX dcterms: <http://purl.org/dc/terms/>
