SELECT DISTINCT ?writtenRep
WHERE {
  # Hyponyms of 'parlare' in CompL-it (ways of speaking = more specific than parlare)
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?parlareWord ontolex:canonicalForm [ ontolex:writtenRep ?parlareWr ] ;
                 ontolex:sense ?parlareSense .
    FILTER(STR(?parlareWr) = "parlare")

    ?word ontolex:sense ?wordSense ;
          ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
    ?wordSense lexinfo:hyponym ?parlareSense .
  }

  # Link CompL-it ?word to LiITA via shared URI
  ?word ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  # No Sicilian translation
  FILTER NOT EXISTS {
    ?translationEntry ontolex:canonicalForm ?italianLemma ;
                      vartrans:translatableAs ?sicilianLexEntry .
    ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
    ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
  }
}

