}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?dialect ?dialectWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:noun .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  FILTER(STRENDS(STR(?italianWord), "polo"))

  ?translationEntry ontolex:canonicalForm ?italianLemma ;
                    vartrans:translatableAs ?dialectEntry .
  ?dialectEntry ontolex:canonicalForm ?dialectLemma .
  ?dialectLemma ontolex:writtenRep ?dialectWord .

  {
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
    BIND("Sicilian" AS ?dialect)
  } UNION {
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
    BIND("Parmigiano" AS ?dialect)
  }
}
ORDER BY ?italianWord ?dialect

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(DISTINCT ?italianWord) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  {
    # Branch 1: Words associated with Sadness (Tristezza) in ELIta
    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
      ?emotionEntry elita:HasEmotion elita:Tristezza .
    }
  }
  UNION
  {
    # Branch 2: Words with Sentix polarity value below -0.8
    ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                   marl:hasPolarity ?polarity ;
                   marl:hasPolarityValue ?polarityValue .
    FILTER(?polarityValue < -0.8)
  }
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?writtenRep ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    {
      # Branch 1: Parts (meronyms) of 'galletto'
      ?galletto ontolex:canonicalForm [ ontolex:writtenRep ?gallWr ] ;
                ontolex:sense ?gallSense .
      FILTER(STR(?gallWr) = "galletto")

      ?partSense lexinfo:partMeronym ?gallSense .
      ?word ontolex:sense ?partSense ;
            ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
      OPTIONAL { ?partSense skos:definition ?definition }
    }
    UNION
    {
      # Branch 2: Words whose definition mentions 'galletto'
      ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
            ontolex:sense ?sense .
      ?sense skos:definition ?definition .
      FILTER(REGEX(STR(?definition), "galletto", "i"))
    }
  }
}

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    {
      # Branch 1: Words with SIMPLE semantic type 'Fruit'
      ?word ontolex:sense ?sense .
      ?sense complit:hasSemanticType ?semanticType .
      FILTER(REGEX(STR(?semanticType), "Fruit", "i"))
    }
    UNION
    {
      # Branch 2: Hyponyms of 'frutto' (more specific types of fruit)
      ?seedWord ontolex:canonicalForm [ ontolex:writtenRep ?seedWr ] ;
                ontolex:sense ?seedSense .
      FILTER(STR(?seedWr) = "frutto")
      ?seedSense lexinfo:hypernym ?hyponymSense .  # ?seedSense is more general than ?hyponymSense
      ?word ontolex:sense ?hyponymSense .
    }
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?italianWord ] .
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?pos (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS ?pos .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma ;
                elita:HasEmotion elita:Tristezza .
}
GROUP BY ?pos
ORDER BY DESC(?count)

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?emotionLabel (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:adjective ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(REGEX(STR(?italianWord), "ente$", "i"))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }
}
GROUP BY ?emotion ?emotionLabel
ORDER BY DESC(?count)

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?dialect (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  {
    GRAPH <http://liita.it/data> {
      ?italianLemma a ?italianLemmaType ;
                    lila:hasPOS lila:verb .
      FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    }
    ?italianEntry ontolex:canonicalForm ?italianLemma ;
                  vartrans:translatableAs ?dialectEntry .
    ?dialectEntry ontolex:canonicalForm ?dialectLemma .
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
    BIND("Sicilian" AS ?dialect)
  } UNION {
    GRAPH <http://liita.it/data> {
      ?italianLemma a ?italianLemmaType ;
                    lila:hasPOS lila:verb .
      FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    }
    ?italianEntry ontolex:canonicalForm ?italianLemma ;
                  vartrans:translatableAs ?dialectEntry .
    ?dialectEntry ontolex:canonicalForm ?dialectLemma .
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
    BIND("Parmigiano" AS ?dialect)
  }
}
GROUP BY ?dialect

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?italianWord ?count
WHERE {
  {
    SELECT ?italianWord (COUNT(DISTINCT ?sicilianWord) AS ?count)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType ;
                      ontolex:writtenRep ?italianWord ;
                      lila:hasPOS lila:noun .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      FILTER(STRENDS(STR(?italianWord), "ente"))
      ?sicItEntry ontolex:canonicalForm ?italianLemma ;
                  vartrans:translatableAs ?sicEntry .
      ?sicEntry ontolex:canonicalForm ?sicLemma .
      ?sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
               ontolex:writtenRep ?sicilianWord .
    }
    GROUP BY ?italianWord
  }
  {
    SELECT (MAX(?n) AS ?maxCount)
    WHERE {
      {
        SELECT ?italianWord (COUNT(DISTINCT ?sicilianWord) AS ?n)
        WHERE {
          GRAPH <http://liita.it/data> {
            ?italianLemma a ?italianLemmaType ;
                          ontolex:writtenRep ?italianWord ;
                          lila:hasPOS lila:noun .
            FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
          }
          FILTER(STRENDS(STR(?italianWord), "ente"))
          ?sicItEntry ontolex:canonicalForm ?italianLemma ;
                      vartrans:translatableAs ?sicEntry .
          ?sicEntry ontolex:canonicalForm ?sicLemma .
          ?sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?sicilianWord .
        }
        GROUP BY ?italianWord
      }
    }
  }
  FILTER(?count = ?maxCount)
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?polarityClass (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma ;
      elita:HasEmotion elita:Amore .

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
      marl:hasPolarity ?polarity .

  BIND(STRAFTER(STR(?polarity), "#") AS ?polarityClass)
}
GROUP BY ?polarityClass
ORDER BY DESC(?count)

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>

SELECT ?italianWord (COUNT(DISTINCT ?parmigianoWord) AS ?count)
       (GROUP_CONCAT(DISTINCT ?parmigianoWord; separator=", ") AS ?parmigianoTranslations)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:verb ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?parmigianoLexEntry .
  ?parmigianoLexEntry ^lime:entry <http://liita.it/data/id/LexicalReources/DialettoParmigiano/Lexicon> ;
                      ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma ontolex:writtenRep ?parmigianoWord .
}
GROUP BY ?italianWord
HAVING (COUNT(DISTINCT ?parmigianoWord) > 4)
ORDER BY DESC(?count)

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?wr (COUNT(DISTINCT ?sense) AS ?count)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] ;
          ontolex:sense ?sense .
    ?sense complit:hasSemanticType ?semanticType .
    FILTER(REGEX(STR(?semanticType), "3_D_location", "i"))
  }
}
GROUP BY ?wr
HAVING (COUNT(DISTINCT ?sense) > 3)
ORDER BY DESC(?count)

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?italianWord (COUNT(DISTINCT ?polarityValue) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity ;
                 marl:hasPolarityValue ?polarityValue .
}
GROUP BY ?italianWord
HAVING (COUNT(DISTINCT ?polarityValue) > 3)

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?hyponymWr (COUNT(DISTINCT ?level2Sense) AS ?count)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    # Find 'personaggio' and its sense
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] ;
          ontolex:sense ?sense .
    FILTER(STR(?wr) = "personaggio")

    # Find level-1 hyponyms of 'personaggio'
    ?sense lexinfo:hypernym ?level1Sense .
    ?hyponymWord ontolex:sense ?level1Sense ;
                 ontolex:canonicalForm [ ontolex:writtenRep ?hyponymWr ] .

    # Find level-2 hyponyms (hyponyms of each level-1 hyponym)
    ?level1Sense lexinfo:hypernym ?level2Sense .
  }
}
GROUP BY ?hyponymWr
HAVING (COUNT(DISTINCT ?level2Sense) > 5)
ORDER BY DESC(?count)

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?italianWord ?maxPolarityValue
WHERE {
  # Compute max Sentix polarity of 'protozoo'
  {
    SELECT (MAX(xsd:float(?protozooPolVal)) AS ?protozooMaxPolarity)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?protozooLemma a ?protozooLemmaType ;
                       ontolex:writtenRep ?protozooWord .
        FILTER(?protozooLemmaType IN (lila:Lemma, lila:Hypolemma))
        FILTER(STR(?protozooWord) = "protozoo")
      }
      ?protozooPolEntry ontolex:canonicalForm ?protozooLemma ;
                        marl:hasPolarity ?protozooPolClass ;
                        marl:hasPolarityValue ?protozooPolVal .
    }
  }

  # Anger (Rabbia) words from ELIta
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion elita:Rabbia .
  }

  # Max Sentix polarity per anger word
  {
    SELECT ?italianLemma (MAX(xsd:float(?polVal)) AS ?maxPolarityValue)
    WHERE {
      ?polEntry ontolex:canonicalForm ?italianLemma ;
                marl:hasPolarity ?polClass ;
                marl:hasPolarityValue ?polVal .
    }
    GROUP BY ?italianLemma
  }

  FILTER(?maxPolarityValue > ?protozooMaxPolarity)
}
ORDER BY DESC(?maxPolarityValue)

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?writtenRep ?count
WHERE {
  {
    SELECT ?writtenRep (COUNT(DISTINCT ?sense) AS ?count)
    WHERE {
      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
              ontolex:sense ?sense .
        ?sense complit:hasSemanticType ?actType .
        FILTER(STRENDS(STR(?actType), "-Act"))
      }
    }
    GROUP BY ?writtenRep
  }

  {
    SELECT (COUNT(DISTINCT ?baseSense) AS ?baseCount)
    WHERE {
      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?baseWord ontolex:canonicalForm [ ontolex:writtenRep ?baseWr ] ;
                 ontolex:sense ?baseSense .
        FILTER(STR(?baseWr) = "base")
      }
    }
  }

  FILTER(?count > ?baseCount)
}
ORDER BY DESC(?count)

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?emotionLabel ?count
WHERE {
  {
    SELECT ?emotion (COUNT(DISTINCT ?italianLemma) AS ?count)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType ;
                      lila:hasPOS lila:adjective .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
    }
    GROUP BY ?emotion
  }

  {
    SELECT (COUNT(DISTINCT ?angerLemma) AS ?angerCount)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?angerLemma a ?angerLemmaType ;
                    lila:hasPOS lila:adjective .
        FILTER(?angerLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?angerEntry ontolex:canonicalForm ?angerLemma .
      GRAPH <http://w3id.org/elita> {
        ?angerEntry elita:HasEmotion elita:Rabbia .
      }
    }
  }

  ?emotion rdfs:label ?emotionLabel .
  FILTER(?count > ?angerCount)
  FILTER(?emotion != elita:Rabbia)
}
ORDER BY DESC(?count)

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?parmigianoWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(REGEX(STR(?italianWord), "^pu", "i"))
  }

  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?parmigianoLexEntry .

  ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?parmigianoWord .
  FILTER(REGEX(STR(?parmigianoWord), "^po", "i"))
}
ORDER BY ?italianWord

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?italianLemma (GROUP_CONCAT(DISTINCT ?italianWord ;separator=", ") AS ?italianWords)
       ?sicilianLemma (GROUP_CONCAT(DISTINCT ?sicilianWord ;separator=", ") AS ?sicilianWords)
WHERE {
  ?sicilianLemma a ?sicilianLemmaType ;
                 dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .
  FILTER(?sicilianLemmaType IN (lila:Lemma, lila:Hypolemma))
  FILTER regex(str(?sicilianWord), "ina$")

  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?italianLexEntry vartrans:translatableAs ?sicilianLexEntry ;
                   ontolex:canonicalForm ?italianLemma .

  ?italianLemma a ?italianLemmaType ;
                dcterms:isPartOf <http://liita.it/data/id/lemma/LemmaBank> ;
                ontolex:writtenRep ?italianWord .
  FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  FILTER regex(str(?italianWord), "ena$")
}
GROUP BY ?italianLemma ?sicilianLemma

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?sicilianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:verb .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?sicilianLexEntry .

  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .

  FILTER(STR(?italianWord) = STR(?sicilianWord))
}
ORDER BY ?italianWord

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:noun .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?polarityEntry1 ontolex:canonicalForm ?italianLemma ;
                  marl:hasPolarity ?p1 ;
                  marl:hasPolarityValue ?v1 .

  ?polarityEntry2 ontolex:canonicalForm ?italianLemma ;
                  marl:hasPolarity ?p2 ;
                  marl:hasPolarityValue ?v2 .

  FILTER(?v1 < ?v2 && (?v2 - ?v1) > 0.25)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT (AVG(?n) AS ?avgSicilianTranslations)
WHERE {
  {
    SELECT ?italianLemma (COUNT(DISTINCT ?sicilianWord) AS ?n)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType ;
                      lila:hasPOS lila:verb .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                       vartrans:translatableAs ?sicilianLexEntry .
      ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
      ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                     ontolex:writtenRep ?sicilianWord .
    }
    GROUP BY ?italianLemma
  }
}

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (AVG(?count) AS ?avgSenses)
WHERE {
  {
    SELECT ?word (COUNT(DISTINCT ?sense) AS ?count)
    WHERE {
      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?word ontolex:sense ?targetSense ;
              ontolex:sense ?sense .
        ?targetSense complit:hasSemanticType ?semType .
        FILTER(REGEX(STR(?semType), "Cause_Change_Location"))
      }
    }
    GROUP BY ?word
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:float(?emotionCount)) AS ?avgEmotionCount)
WHERE {
  {
    SELECT ?italianLemma (COUNT(DISTINCT ?emotion) AS ?emotionCount)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }

      ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                     marl:hasPolarity ?polarity ;
                     marl:hasPolarityValue ?polarityValue .
      FILTER(xsd:float(?polarityValue) > 0.8)

      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
    }
    GROUP BY ?italianLemma
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?emotionLabel
       (COUNT(DISTINCT ?italianLemma) AS ?count)
       (AVG(xsd:float(?polarityValue)) AS ?avgPolarityValue)
       (COUNT(DISTINCT ?sicilianCountVar) AS ?withSicilian)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity ;
                 marl:hasPolarityValue ?polarityValue .

  OPTIONAL {
    ?italianSicilianEntry ontolex:canonicalForm ?italianLemma ;
                          vartrans:translatableAs ?sicilianLexEntry .
    ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
    ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
    BIND(?italianLemma AS ?sicilianCountVar)
  }
}
GROUP BY ?emotion ?emotionLabel
ORDER BY ?emotionLabel

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?pos
       (COUNT(DISTINCT ?italianLemma)    AS ?count)
       (COUNT(DISTINCT ?sicItalianLemma) AS ?withSicilian)
       (COUNT(DISTINCT ?parItalianLemma) AS ?withParmigiano)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS ?pos .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  OPTIONAL {
    ?italianSicEntry ontolex:canonicalForm ?italianLemma ;
                     vartrans:translatableAs ?sicEntry .
    ?sicEntry ontolex:canonicalForm ?sicilianLemma .
    ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
    BIND(?italianLemma AS ?sicItalianLemma)
  }

  OPTIONAL {
    ?italianParEntry ontolex:canonicalForm ?italianLemma ;
                     vartrans:translatableAs ?parEntry .
    ?parEntry ontolex:canonicalForm ?parmigianoLemma .
    ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
    BIND(?italianLemma AS ?parItalianLemma)
  }
}
GROUP BY ?pos
ORDER BY DESC(?count)

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?polarity
  (COUNT(DISTINCT ?italianLemma) AS ?count)
  (COUNT(DISTINCT IF(BOUND(?emotionEntry), ?italianLemma, ?none)) AS ?withEmotion)
  (COUNT(DISTINCT IF(BOUND(?parLemma), ?italianLemma, ?none)) AS ?withParmigiano)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity .

  OPTIONAL {
    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
      ?emotionEntry elita:HasEmotion ?emotion .
    }
  }

  OPTIONAL {
    ?parItEntry ontolex:canonicalForm ?italianLemma ;
                vartrans:translatableAs ?parEntry .
    ?parEntry ontolex:canonicalForm ?parLemma .
    ?parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
  }
}
GROUP BY ?polarity
ORDER BY ?polarity

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?dialect ?count ?linkedLemmas ?italianLemmas
WHERE {
  {
    SELECT ("Sicilian" AS ?dialect)
           (COUNT(DISTINCT ?sicilianLemma) AS ?count)
           (COUNT(DISTINCT ?sicilianLinked) AS ?linkedLemmas)
           (COUNT(DISTINCT ?italianLemmaSic) AS ?italianLemmas)
    WHERE {
      ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
      OPTIONAL {
        ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
        ?italianLexEntry vartrans:translatableAs ?sicilianLexEntry ;
                         ontolex:canonicalForm ?italianLemmaSic .
        BIND(?sicilianLemma AS ?sicilianLinked)
      }
    }
  }
  UNION
  {
    SELECT ("Parmigiano" AS ?dialect)
           (COUNT(DISTINCT ?parmigianoLemma) AS ?count)
           (COUNT(DISTINCT ?parmigianoLinked) AS ?linkedLemmas)
           (COUNT(DISTINCT ?italianLemmaPar) AS ?italianLemmas)
    WHERE {
      ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
      OPTIONAL {
        ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
        ?italianLexEntryPar vartrans:translatableAs ?parmigianoLexEntry ;
                            ontolex:canonicalForm ?italianLemmaPar .
        BIND(?parmigianoLemma AS ?parmigianoLinked)
      }
    }
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?lemmaBank
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
        dcterms:isPartOf ?lemmaBank .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}

# This query counts the number of lemmas in each LiITA lemma bank using dcterms:isPartOf to identify the resource.
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT ?resource (COUNT(DISTINCT ?lemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma dcterms:isPartOf ?resource .
  }
}
GROUP BY ?resource
ORDER BY DESC(?count)

PREFIX elita: <http://w3id.org/elita/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?emotion ?emotionLabel
WHERE {
  GRAPH <http://w3id.org/elita> {
    ?emotion rdf:type elita:Emotion .
    ?emotion rdfs:label ?emotionLabel .
  }
}
ORDER BY ?emotionLabel
